package com.captainsledger;

import lombok.Getter;

@Getter
public enum AccountType
{
    UNKNOWN(-1),
    REGULAR(-1),
    IRONMAN(2),
    HARDCORE_IRONMAN(10),
    ULTIMATE_IRONMAN(3);

    private final int modIcon;

    AccountType(int modIcon)
    {
        this.modIcon = modIcon;
    }

    public boolean hasModIcon()
    {
        return modIcon >= 0;
    }

    public boolean isIronman()
    {
        return this == IRONMAN
                || this == HARDCORE_IRONMAN
                || this == ULTIMATE_IRONMAN;
    }
}

package com.captainsledger;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("captainsledger")
public interface CaptainsLedgerConfig extends Config
{
	@ConfigItem(
			keyName = "hourlyRate",
			name = "Default Hourly Rate",
			description = "Default GP per hour",
			position = 1
	)
	default int hourlyRate()
	{
		return 1_000_000;
	}
}

/*
 * Development launcher for running this plugin locally from the IDE/Gradle.
 * Not used by RuneLite when the plugin is loaded normally.
 */

package com.captainsledger;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CaptainsLedgerLauncher
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(CaptainsLedgerPlugin.class);
        RuneLite.main(args);
    }
}

package com.captainsledger;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
